import './style.css';

import * as React from 'react';

import { cn } from '@/lib/utils';

/*
 * @author: @joao-carmassi
 * @description: Unified ambient aura wrapper with beam and shine variants.
 * - Default (no variant): diffuse rotating conic-gradient halo.
 * - variant="beam": focused narrow arc of light that travels around the border.
 * - variant="shine": sweeping radial-gradient highlight that glides across the border.
 * All variants share the same high-quality blur/glow layers.
 * @version: 2.0.0
 * @date: 2026-07-06
 * @license: MIT
 */

interface AuraBeamProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  'color'
> {
  /**
   * Visual variant of the effect.
   * - omitted: diffuse rotating conic-gradient aura (default)
   * - "beam": focused narrow arc that continuously travels along the border
   * - "shine": sweeping radial-gradient highlight that passes across the border
   */
  variant?: 'beam' | 'shine';
  /**
   * Animation cycle duration in seconds.
   * @default 6
   */
  duration?: number;
  /**
   * Border glow color(s).
   * - string: single solid color
   * - string[]: gradient for beam ([from, to]) or multi-stop for shine
   * @default "hsl(var(--primary))"
   */
  color?: string | string[];
  /**
   * Thickness of the glow border in pixels.
   * @default 2
   */
  borderWidth?: number;
  /**
   * Corner radius — should match the wrapped element.
   * @default "0.75rem"
   */
  radius?: string;
  children: React.ReactNode;
}

export function AuraBeam({
  variant,
  duration,
  color,
  borderWidth,
  radius,
  className,
  style,
  children,
  ...props
}: AuraBeamProps): React.ReactNode {
  const cssVars = {} as React.CSSProperties & Record<string, string>;

  if (duration !== undefined) cssVars['--aura-duration'] = `${duration}s`;
  if (borderWidth !== undefined) cssVars['--aura-padding'] = `${borderWidth}px`;
  if (radius !== undefined) cssVars['--aura-radius'] = radius;

  const colors = Array.isArray(color) ? color : color ? [color] : [];
  if (colors.length > 0) {
    cssVars['--aura-color'] = colors[0];
    cssVars['--aura-color-from'] = colors[0];
    cssVars['--aura-color-to'] = colors[1] ?? colors[0];
  }

  // Shine with multiple colors: inject a multi-stop radial gradient inline
  const shineInline: React.CSSProperties =
    variant === 'shine' && colors.length > 1
      ? {
          backgroundImage: `radial-gradient(transparent, transparent, ${colors.join(', ')}, transparent, transparent)`,
        }
      : {};

  return (
    <div
      className={cn('aura-beam', className)}
      data-variant={variant}
      style={{ ...cssVars, ...shineInline, ...style }}
      {...props}
    >
      {children}
    </div>
  );
}

[data-variant='default'] {
  --pulse-color: var(--primary);
}
[data-variant='destructive'] {
  --pulse-color: var(--destructive);
}
[data-variant='secondary'] {
  --pulse-color: var(--secondary-foreground);
}
[data-variant='outline'] {
  --pulse-color: var(--ring);
}
[data-variant='ghost'] {
  --pulse-color: var(--ring);
}

.before\:animate-shine-effect::before {
  animation: shine-effect 3s ease-out infinite;
}

.animate-rainbow-effect {
  animation: rainbow-effect 3s linear infinite;
}

.animate-pulsating-effect {
  animation: pulsating-effect 1.5s ease-out infinite;
}

.card-shine-effect {
  animation: card-shine-effect var(--duration) infinite linear;
}

@keyframes shine-effect {
  0% {
    background-position: 200% 0;
  }
  25% {
    background-position: -200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes rainbow-effect {
  0% {
    background-position: 0%;
  }
  100% {
    background-position: 200%;
  }
}

@keyframes pulsating-effect {
  0% {
    box-shadow: 0 0 0 0 var(--pulse-color, currentColor);
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

@keyframes card-shine-effect {
  0% {
    background-position: 0% 0%;
  }
  50% {
    background-position: 100% 100%;
  }
  to {
    background-position: 0% 0%;
  }
}

/* ─── Aura Beam ─────────────────────────────────────────────────────────── */

@property --aura-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

@keyframes aura-spin {
  to {
    --aura-angle: 360deg;
  }
}

.aura-beam {
  --aura-padding: 2px;
  --aura-radius: 0.75rem;
  --aura-duration: 6s;
  --aura-color: var(--primary);
  --aura-color-from: var(--aura-color);
  --aura-color-to: var(--aura-color);

  position: relative;
  display: inline-block;
  padding: var(--aura-padding);
  border-radius: calc(var(--aura-radius) + var(--aura-padding));
  color: var(--aura-color);

  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 220deg,
    currentColor 280deg,
    currentColor 360deg
  );

  animation: aura-spin var(--aura-duration) linear infinite;
}

.aura-beam > * {
  position: relative;
  z-index: 2;
  border-radius: var(--aura-radius);
}

.aura-beam::before,
.aura-beam::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: inherit;
  pointer-events: none;
  z-index: 0;
}

.aura-beam::before {
  filter: blur(6px);
  opacity: 0.65;
}

.aura-beam::after {
  filter: blur(18px);
  opacity: 0.35;
}

.aura-beam-rainbow {
  background-image: conic-gradient(
    from var(--aura-angle),
    #ef4444,
    #f97316,
    #eab308,
    #22c55e,
    #06b6d4,
    #3b82f6,
    #a855f7,
    #ef4444
  );
}

.aura-beam-holo {
  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    #22d3ee 60deg,
    #a78bfa 140deg,
    #f0abfc 220deg,
    #67e8f9 300deg,
    transparent 360deg
  );
}

.aura-beam-glow::before {
  filter: blur(10px);
  opacity: 0.8;
}

.aura-beam-glow::after {
  filter: blur(28px);
  opacity: 0.55;
}

/* ─── Beam variant ────────────────────────────────────────────────────────── */

.aura-beam[data-variant='beam'] {
  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 275deg,
    var(--aura-color-from) 305deg,
    var(--aura-color-to) 325deg,
    transparent 360deg
  );
}

.aura-beam[data-variant='beam']::before {
  filter: blur(4px);
  opacity: 0.85;
}

.aura-beam[data-variant='beam']::after {
  filter: blur(22px);
  opacity: 0.55;
}

/* ─── Shine variant ───────────────────────────────────────────────────────── */

@keyframes aura-shine {
  0% {
    background-position: 0% 0%;
  }
  50% {
    background-position: 100% 100%;
  }
  100% {
    background-position: 0% 0%;
  }
}

.aura-beam[data-variant='shine'] {
  background-image: radial-gradient(
    transparent,
    transparent,
    var(--aura-color),
    transparent,
    transparent
  );
  background-size: 300% 300%;
  animation: aura-shine var(--aura-duration) linear infinite;
}

.aura-beam[data-variant='shine']::before {
  filter: blur(8px);
  opacity: 0.7;
  animation: aura-shine var(--aura-duration) linear infinite;
}

.aura-beam[data-variant='shine']::after {
  filter: blur(26px);
  opacity: 0.42;
  animation: aura-shine var(--aura-duration) linear infinite;
}
